#!/usr/bin/env node
import { writeFile } from "node:fs/promises";
import { resolve } from "node:path";
import { collectFiles } from "./core/files.js";
import { initConfig, loadConfig } from "./core/config.js";
import { scanRepository } from "./core/scanner.js";
import { hasCiFailure, formatSummary, toJson, toText } from "./core/report.js";
import { applySafeFixes } from "./rules/hygiene.js";
function usage() { return `gODtECH Steward\n\nUsage:\n  steward init [path]\n  steward scan [path] [--json] [--ci]\n  steward doctor [path] [--json] [--ci]\n  steward report [path] --output <file>\n  steward fix [path] --safe [--dry-run]\n  steward --version\n`; }
function option(args, name) { const index = args.indexOf(name); return index >= 0 ? args[index + 1] : undefined; }
function targetPath(args) { const commandWords = new Set(["scan", "doctor", "report", "fix", "init"]); for (let i = 1; i < args.length; i += 1) { const arg = args[i]; if (arg === "--output") { i += 1; continue; } if (!arg.startsWith("--") && !commandWords.has(arg)) return arg; } return "."; }
function printDoctor(result) { console.log(toText(result)); console.log(""); console.log(formatSummary(result)); }
async function main() { const args = process.argv.slice(2); const command = args[0] ?? "help"; if (command === "--version" || command === "-v") { console.log("0.1.0"); return; } if (command === "help" || command === "--help" || command === "-h") { console.log(usage()); return; } const root = resolve(targetPath(args)); if (command === "init") { const created = await initConfig(root); console.log(created ? "Created .steward.json" : ".steward.json already exists"); return; } if (!["scan", "doctor", "report", "fix"].includes(command)) throw new Error(`Unknown command: ${command}\n\n${usage()}`); const result = await scanRepository(root); if (command === "fix") { if (!args.includes("--safe")) throw new Error("Refusing to modify files without explicit --safe."); const candidates = result.findings.filter((finding) => finding.fixable); if (candidates.length === 0) { console.log("No safe fixes are available."); return; } console.log(`${candidates.length} safe remediation finding(s) available.`); for (const finding of candidates) console.log(`- ${finding.path ?? "repository"}: ${finding.message}`); if (args.includes("--dry-run")) { console.log("Dry run only. No files changed."); return; } const config = (await loadConfig(root)).config; const files = await collectFiles(root, config); const changed = applySafeFixes(files, candidates); console.log(changed.length ? `Safe fixes applied to ${changed.length} file(s):\n${changed.map((file) => `- ${file}`).join("\n")}` : "No files required a change."); return; } if (command === "report") { const output = option(args, "--output"); if (!output) throw new Error("report requires --output <file>"); await writeFile(resolve(root, output), toJson(result) + "\n", "utf8"); console.log(`Report written to ${resolve(root, output)}`); } else if (command === "doctor") { if (args.includes("--json")) console.log(toJson(result)); else printDoctor(result); } else if (args.includes("--json")) console.log(toJson(result)); else console.log(toText(result)); if (args.includes("--ci")) { const failOn = (await loadConfig(root)).config.ci.failOn; if (hasCiFailure(result, failOn)) process.exitCode = 1; } }
main().catch((error) => { console.error(error instanceof Error ? error.message : String(error)); process.exitCode = 2; });
